import { getAds } from '@/entities/ad';
import type { Ad } from '@/entities/ad';
import { EmptyPlaceholder } from '@/components/ui/EmptyPlaceholder';
import { ListEndMessage } from '@/components/ui/ListEndMessage';
import { SkeletonLoader } from '@/components/ui/SkeletonLoader';
import { useGridColumns } from '@/shared/hooks/use-grid-columns';
import { usePageScrollLazyLoading } from '@/shared/hooks/use-page-scroll-lazy-loading';
import { getItemGridClasses } from '@/shared/utils/get-item-grid-classes';

import { AdCard } from './components/AdCard';

type AdsListingProps = {
  categorySlug?: string;
  emptyText?: string;
  ads?: Ad[];
  compact?: boolean;
};

function AdGrid({ ads, emptyText, categorySlug, compact = false }: { ads: Ad[]; emptyText: string; categorySlug?: string; compact?: boolean }) {
  if (!ads.length) {
    return <EmptyPlaceholder>{emptyText}</EmptyPlaceholder>;
  }
  return (
    <div className={getItemGridClasses(compact ? 'compact' : 'default')}>
      {ads.map((ad) => (
        <AdCard key={ad.id} ad={ad} currentCategorySlug={categorySlug} />
      ))}
    </div>
  );
}

function AdsListingFetched({
  categorySlug,
  emptyText,
  initialChunkSize,
  chunkSize,
  compact = false,
}: {
  categorySlug?: string;
  emptyText: string;
  initialChunkSize: number;
  chunkSize: number;
  compact?: boolean;
}) {
  const { items, isLoading, hasMore, error } = usePageScrollLazyLoading({
    fetchFunction: () => getAds({ categorySlug, sort: 'createdAt:desc' }),
    initialChunkSize,
    chunkSize,
  });

  if (error) {
    return (
      <div className="rounded-2xl border border-destructive/20 p-5">
        <p className="text-sm text-destructive">Не удалось загрузить объявления: {error}</p>
      </div>
    );
  }

  if (!isLoading && !items.length) {
    return <EmptyPlaceholder>{emptyText}</EmptyPlaceholder>;
  }

  if (isLoading && !items.length) {
    return (
      <SkeletonLoader
        variant="card"
        layout="grid"
        count={initialChunkSize}
        className={getItemGridClasses(compact ? 'compact' : 'default')}
        ariaLabel="Загружаем объявления"
      />
    );
  }

  return (
    <div className="space-y-4">
      <div className={getItemGridClasses(compact ? 'compact' : 'default')}>
        {items.map((ad) => (
          <AdCard key={ad.id} ad={ad} currentCategorySlug={categorySlug} />
        ))}
      </div>

      {isLoading && items.length > 0 && (
        <SkeletonLoader
          variant="card"
          layout="grid"
          count={chunkSize}
          className={getItemGridClasses(compact ? 'compact' : 'default')}
          ariaLabel="Загружаем ещё объявления"
        />
      )}

      {!hasMore && items.length > 0 && (
        <ListEndMessage>Показаны все объявления</ListEndMessage>
      )}
    </div>
  );
}

export function AdsListing({
  categorySlug,
  emptyText = 'Объявления пока не размещены.',
  ads: externalAds,
  compact = false,
}: AdsListingProps) {
  const columns = useGridColumns(compact ? 'compact' : 'default');
  const chunkSize = columns * 2;
  const initialChunkSize = columns * 3;

  if (externalAds !== undefined) {
    return <AdGrid ads={externalAds} emptyText={emptyText} categorySlug={categorySlug} compact={compact} />;
  }

  return (
    <AdsListingFetched
      categorySlug={categorySlug}
      emptyText={emptyText}
      initialChunkSize={initialChunkSize}
      chunkSize={chunkSize}
      compact={compact}
    />
  );
}

import { useNavigate } from 'react-router-dom';

import { getAds } from '@/entities/ad/api/get-ads';
import { SkeletonLoader } from '@/components/ui/SkeletonLoader';
import { AdCard } from '@/widgets/AdsListing/components/AdCard/AdCard';
import { HorizontalScrollSection } from '@/widgets/HorizontalScrollSection';
import { useHorizontalScrollLazyLoading } from '@/shared/hooks/use-horizontal-scroll-lazy-loading';

type LatestAdsProps = {
  initialChunkSize?: number;
  chunkSize?: number;
  className?: string;
};

export function LatestAds({
  initialChunkSize = 8,
  chunkSize = 4,
  className,
}: LatestAdsProps) {
  const navigate = useNavigate();

  const {
    items,
    isLoading,
    hasMore,
    error,
    scrollContainerRef,
    handleScroll,
  } = useHorizontalScrollLazyLoading({
    fetchFunction: async (offset, limit) => {
      const response = await getAds({
        sort: 'createdAt:desc',
      });

      // Client-side pagination
      const start = offset;
      const end = start + limit;
      return response.slice(start, end);
    },
    initialChunkSize,
    chunkSize,
  });

  const handleSeeAll = () => {
    navigate('/ads');
  };

  if (error) {
    return (
      <HorizontalScrollSection
        title="Последние объявления"
        className={className}
      >
        <div className="text-center text-muted-foreground py-8 w-full min-w-[280px]">
          Не удалось загрузить объявления: {error}
        </div>
      </HorizontalScrollSection>
    );
  }

  return (
    <HorizontalScrollSection
      title="Последние объявления"
      onSeeAllClick={handleSeeAll}
      onScroll={handleScroll}
      ref={scrollContainerRef}
      className={className}
    >
      {isLoading && items.length === 0 ? (
        Array.from({ length: initialChunkSize }).map((_, index) => (
          <SkeletonLoader
            key={`skeleton-${index}`}
            variant="card"
            itemClassName="w-72 shrink-0"
            ariaLabel="Загружаем объявление"
          />
        ))
      ) : (
        <>
          {items.map((ad) => (
            <div key={ad.id} className="min-w-0 w-72 flex-shrink-0">
              <AdCard ad={ad} />
            </div>
          ))}

          {isLoading && hasMore && (
            Array.from({ length: Math.min(chunkSize, 2) }).map((_, index) => (
              <SkeletonLoader
                key={`loading-${index}`}
                variant="card"
                itemClassName="w-72 shrink-0"
                ariaLabel="Загружаем ещё объявление"
              />
            ))
          )}
        </>
      )}
    </HorizontalScrollSection>
  );
}

import { getProducts } from '@/entities/product/api/get-products';
import { EmptyPlaceholder } from '@/components/ui/EmptyPlaceholder';
import { ListEndMessage } from '@/components/ui/ListEndMessage';
import { SkeletonLoader } from '@/components/ui/SkeletonLoader';
import { PLATFORM_SECTION } from '@/shared/platform';
import { useGridColumns } from '@/shared/hooks/use-grid-columns';
import { usePageScrollLazyLoading } from '@/shared/hooks/use-page-scroll-lazy-loading';
import { getItemGridClasses } from '@/shared/utils/get-item-grid-classes';
import { ProductCard } from '@/widgets/Catalog/components/ProductGrid/components/ProductCard';


type ProductsListingProps = {
  categorySlug?: string;
  emptyText?: string;
};

export function ProductsListing({
  categorySlug,
  emptyText = 'Товары пока не добавлены.',
}: ProductsListingProps) {
  const columns = useGridColumns('default');
  const chunkSize = columns * 2;
  const initialChunkSize = columns * 3;

  const {
    items,
    isLoading,
    hasMore,
    error,
  } = usePageScrollLazyLoading({
    fetchFunction: async () => {
      const response = await getProducts({
        section: PLATFORM_SECTION.MARKET,
        categorySlug,
        sortRules: [{ field: 'title', direction: 'desc' }],
      });

      return response.sort((a, b) =>
        new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
      );
    },
    initialChunkSize,
    chunkSize,
  });

  if (error) {
    return (
      <div className="rounded-2xl border border-destructive/20 p-5">
        <p className="text-sm text-destructive">
          Не удалось загрузить товары: {error}
        </p>
      </div>
    );
  }

  if (!isLoading && !items.length) {
    return <EmptyPlaceholder>{emptyText}</EmptyPlaceholder>;
  }

  if (isLoading && !items.length) {
    return (
      <SkeletonLoader
        variant="card"
        layout="grid"
        count={initialChunkSize}
        className={getItemGridClasses()}
        ariaLabel="Загружаем товары"
      />
    );
  }

  return (
    <div className="space-y-4">
      <div className={getItemGridClasses()}>
        {items.map((product) => (
          <ProductCard
            key={product.id}
            section={PLATFORM_SECTION.MARKET}
            product={product}
          />
        ))}
      </div>

      {isLoading && items.length > 0 && (
        <SkeletonLoader
          variant="card"
          layout="grid"
          count={chunkSize}
          className={getItemGridClasses()}
          ariaLabel="Загружаем ещё товары"
        />
      )}

      {!hasMore && items.length > 0 && (
        <ListEndMessage>Показаны все товары</ListEndMessage>
      )}
    </div>
  );
}

