import type { CatalogCategory } from '@/shared/types/catalog-category';
import { cn } from '@/shared/utils/cn';

type CategoryTreeProps = {
  categories: CatalogCategory[];
  selectedCategorySlug?: string;
  onCategoryChange: (categorySlug?: string) => void;
};

function getChildrenCategories(categories: CatalogCategory[], parentId?: string) {
  return categories.filter((category) => category.parentId === parentId);
}

type CategoryTreeLevelProps = {
  categories: CatalogCategory[];
  parentId?: string;
  selectedCategorySlug?: string;
  onCategoryChange: (categorySlug?: string) => void;
  level?: number;
};

function CategoryTreeLevel({
  categories,
  parentId,
  selectedCategorySlug,
  onCategoryChange,
  level = 0,
}: CategoryTreeLevelProps) {
  const childrenCategories = getChildrenCategories(categories, parentId);

  if (!childrenCategories.length) {
    return null;
  }

  return (
    <div className={cn('flex flex-col gap-1', level > 0 && 'pl-4')}>
      {childrenCategories.map((category) => {
        const isActive = selectedCategorySlug === category.slug;

        return (
          <div key={category.id} className="space-y-1">
            <button
              type="button"
              onClick={() => onCategoryChange(category.slug)}
              className={cn(
                'w-full cursor-pointer rounded-md border border-border px-3 py-1 text-left text-sm transition-colors',
                isActive
                  ? 'bg-primary text-primary-foreground'
                  : 'bg-background hover:bg-muted',
              )}
            >
              {category.name}
            </button>

            <CategoryTreeLevel
              categories={categories}
              parentId={category.id}
              selectedCategorySlug={selectedCategorySlug}
              onCategoryChange={onCategoryChange}
              level={level + 1}
            />
          </div>
        );
      })}
    </div>
  );
}

export function CategoryTree({
  categories,
  selectedCategorySlug,
  onCategoryChange,
}: CategoryTreeProps) {
  return (
    <div className="w-full space-y-2">
      <button
        type="button"
        onClick={() => onCategoryChange(undefined)}
        className={cn(
          'w-full cursor-pointer rounded-md border border-border px-3 py-1 text-left text-sm transition-colors',
          !selectedCategorySlug
            ? 'bg-primary text-primary-foreground'
            : 'bg-background hover:bg-muted',
        )}
      >
        Все товары
      </button>

      <CategoryTreeLevel
        categories={categories}
        selectedCategorySlug={selectedCategorySlug}
        onCategoryChange={onCategoryChange}
      />
    </div>
  );
}

import { useNavigate } from 'react-router-dom';

import { getProducts } from '@/entities/product/api/get-products';
import { SkeletonLoader } from '@/components/ui/SkeletonLoader';
import { ProductCard } from '@/widgets/Catalog/components/ProductGrid/components/ProductCard/ProductCard';
import { HorizontalScrollSection } from '@/widgets/HorizontalScrollSection';
import { useHorizontalScrollLazyLoading } from '@/shared/hooks/use-horizontal-scroll-lazy-loading';
import { PLATFORM_SECTION } from '@/shared/platform';

type LatestProductsProps = {
  initialChunkSize?: number;
  chunkSize?: number;
  className?: string;
};

export function LatestProducts({
  initialChunkSize = 8,
  chunkSize = 4,
  className,
}: LatestProductsProps) {
  const navigate = useNavigate();

  const {
    items,
    isLoading,
    hasMore,
    error,
    scrollContainerRef,
    handleScroll,
  } = useHorizontalScrollLazyLoading({
    fetchFunction: async (offset, limit) => {
      const response = await getProducts({
        section: PLATFORM_SECTION.MARKET,
        sortRules: [{ field: 'title', direction: 'desc' }],
      });

      // Client-side pagination - sort by creation date client-side since API doesn't support it
      const sortedResponse = response.sort((a, b) => 
        new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
      );

      const start = offset;
      const end = start + limit;
      return sortedResponse.slice(start, end);
    },
    initialChunkSize,
    chunkSize,
  });

  const handleSeeAll = () => {
    navigate('/market');
  };

  if (error) {
    return (
      <HorizontalScrollSection
        title="Товары"
        className={className}
      >
        <div className="text-center text-muted-foreground py-8 w-full min-w-[280px]">
          Не удалось загрузить товары: {error}
        </div>
      </HorizontalScrollSection>
    );
  }

  return (
    <HorizontalScrollSection
      title="Товары"
      onSeeAllClick={handleSeeAll}
      onScroll={handleScroll}
      ref={scrollContainerRef}
      className={className}
    >
      {isLoading && items.length === 0 ? (
        Array.from({ length: initialChunkSize }).map((_, index) => (
          <SkeletonLoader
            key={`skeleton-${index}`}
            variant="card"
            itemClassName="w-72 shrink-0"
            ariaLabel="Загружаем товар"
          />
        ))
      ) : (
        <>
          {items.map((product) => (
            <div key={product.id} className="min-w-0 w-72 flex-shrink-0">
              <ProductCard
                section={PLATFORM_SECTION.MARKET}
                product={product}
                showAddToCartButton={true}
                showBuyNowButton={true}
              />
            </div>
          ))}

          {isLoading && hasMore && (
            Array.from({ length: Math.min(chunkSize, 2) }).map((_, index) => (
              <SkeletonLoader
                key={`loading-${index}`}
                variant="card"
                itemClassName="w-72 shrink-0"
                ariaLabel="Загружаем ещё товар"
              />
            ))
          )}
        </>
      )}
    </HorizontalScrollSection>
  );
}

