import type { CartStoreItem } from '@/entities/cart';
import { FavouriteButton } from '@/entities/favourite';
import { formatPrice } from '@/shared/utils/format-price';
import { ProductQuantityCounter } from '@/widgets/ProductQuantityCounter';

import { calculateCartItemTotal } from '../../logic/calculate-cart-item-total';
import { CartItemCard } from '../CartItemCard/CartItemCard';

type CartProductItemCardProps = {
  item: CartStoreItem;
  onRemove: (configurationKey: string) => void;
};

export function CartProductItemCard({ item, onRemove }: CartProductItemCardProps) {
  const { product, quantity } = item;
  const image = product.images[0];
  const itemTotal = calculateCartItemTotal(item);
  const selectedById = new Map(
    (item.selectedAdditions ?? []).map((addition) => [
      addition.additionId,
      addition,
    ]),
  );
  const additionLines = (product.additions ?? []).flatMap((addition) => {
    const selected = selectedById.get(addition.id);
    if (!selected || selected.type !== addition.type) return [];
    if (
      addition.type === 'boolean' &&
      selected.type === 'boolean' &&
      !selected.value &&
      !addition.required
    ) return [];
    const total =
      addition.type === 'boolean'
        ? selected.value
          ? addition.price
          : 0
        : Number(selected.value) * addition.price;
    const value =
      addition.type === 'boolean'
        ? selected.value
          ? 'Да'
          : 'Нет'
        : `${selected.value} ${addition.unitLabel} × ${formatPrice(addition.price)}`;
    return [`${addition.title}: ${value}, ${total ? `+${formatPrice(total)}` : formatPrice(0)}`];
  });

  return (
    <CartItemCard
      href={`/market/product/${product.slug}`}
      imageUrl={image?.url}
      imageAlt={image?.alt ?? product.title}
      placeholderText="Нет изображения"
      title={product.title}
      category={
        <div className="space-y-1 text-sm text-muted-foreground">
          <p>{product.category.name}</p>
          {additionLines.map((line) => <p key={line}>{line}</p>)}
          {additionLines.length > 0 && (
            <p>Цена единицы: {formatPrice(item.configuredUnitPrice)}</p>
          )}
        </div>
      }
      price={<p className="text-base font-semibold sm:text-lg">{formatPrice(itemTotal)}</p>}
      priceMeta={`${quantity} × ${formatPrice(product.price)}`}
      actions={
        <div className="w-36 sm:w-40">
          <ProductQuantityCounter
            productId={item.configurationKey ?? product.id}
            variant="details"
          />
        </div>
      }
      favouriteButton={
        <FavouriteButton
          item={{ productId: product.id }}
          className="size-8 rounded-lg bg-muted hover:bg-muted/80"
        />
      }
      onRemove={() => onRemove(item.configurationKey ?? product.id)}
    />
  );
}
import type { CartAdItem } from '@/entities/cart';
import { FavouriteButton } from '@/entities/favourite';
import { formatPrice } from '@/shared/utils/format-price';
import { LinkifyText } from '@/shared/utils/linkify';

import { CartItemCard } from '../CartItemCard/CartItemCard';

type CartAdItemCardProps = {
  item: CartAdItem;
  onRemove: (adId: string) => void;
};

const contactBadgeClass =
  'inline items-center rounded-md bg-muted/60 px-2 py-1 text-xs font-medium text-foreground transition-colors sm:px-3 sm:py-1.5 sm:text-sm';

function getContactValues(ad: CartAdItem['ad']): string[] {
  return [
    ad.contactPhone,
    ad.contactTelegram,
    ad.contactEmail,
    ad.contactOther,
  ].filter((value): value is string => Boolean(value));
}

export function CartAdItemCard({ item, onRemove }: CartAdItemCardProps) {
  const { ad } = item;
  const image = ad.images?.[0];
  const sellerName = ad.seller?.nickname ?? 'Продавец';
  const contactValues = getContactValues(ad);

  return (
    <CartItemCard
      href={`/ads/ad/${ad.slug}`}
      imageUrl={image?.url}
      imageAlt={image?.alt ?? ad.title}
      title={ad.title}
      category={
        ad.category ? (
          <p className="text-xs text-muted-foreground sm:text-sm">{ad.category.name}</p>
        ) : undefined
      }
      price={<p className="text-base font-semibold sm:text-lg">{formatPrice(ad.price)}</p>}
      priceMeta="Объявление"
      favouriteButton={
        <FavouriteButton
          item={{ adId: ad.id }}
          className="size-8 rounded-lg bg-muted hover:bg-muted/80"
        />
      }
      actions={
        <div className="flex flex-col gap-2 rounded-xl text-xs sm:gap-2 sm:text-sm">
          <span className="font-medium text-foreground">{sellerName}</span>

          {contactValues.length > 0 ? (
            <div className="flex flex-wrap gap-2">
              {contactValues.map((value, index) => (
                <span key={`${value}-${index}`} className={contactBadgeClass}>
                  <LinkifyText text={value} renderLinks={false} />
                </span>
              ))}
            </div>
          ) : (
            <p className="text-sm text-muted-foreground">Продавец пока не указал контакты.</p>
          )}
        </div>
      }
      onRemove={() => onRemove(ad.id)}
    />
  );
}
import { Link } from 'react-router-dom';

import { FavouriteButton } from '@/entities/favourite';
import type { Product } from '@/entities/product';
import {
  getPlatformProductHref,
  type PlatformSectionId,
} from '@/shared/platform';
import { ItemActions } from '@/widgets/ItemActions';

import { ItemGallery } from '@/widgets/ItemGallery';

import { ProductCardContent } from './components/ProductCardContent';

type ProductCardProps = {
  section: PlatformSectionId;
  product: Product;
  currentCategorySlug?: string;
  showAddToCartButton?: boolean;
  showBuyNowButton?: boolean;
  showAdditionsSummary?: boolean;
};

export function ProductCard({
  section,
  product,
  currentCategorySlug,
  showAddToCartButton = true,
  showBuyNowButton = true,
  showAdditionsSummary = false,
}: ProductCardProps) {
  return (
    <Link
      to={getPlatformProductHref(product.slug)}
      className="group relative flex h-full flex-col overflow-hidden rounded-xl p-1 hover:bg-primary/3">
      <div className="relative">
        <ItemGallery images={product.images} title={product.title} />

        <div
          className="absolute right-2 top-2 z-10"
          onClick={(e) => e.preventDefault()}
        >
          <FavouriteButton item={{ productId: product.id }} />
        </div>
      </div>

      <ProductCardContent
        section={section}
        product={product}
